def vocab(id, chinese, pinyin, meaning, example, collocations, de, th):
    return {"id": id, "chinese": chinese, "pinyin": pinyin, "meaning": meaning, "example": example, "collocations": collocations, "gloss": {"de": de, "th": th}, "sourceRefs": [], "origin": "supplementary"}


def choice(id, prompt, options, answer, explanation, skill="comprehension", layer="understand", reading_id=None):
    return {"id": id, "type": "choice", "prompt": prompt, "options": [{"id": str(i), "text": s} for i, s in enumerate(options)], "answer": str(answer), "explanation": explanation, "skill": skill, "layer": layer, "readingId": reading_id, "sourceRefs": [], "origin": "supplementary"}


def cloze(id, prompt, answers, explanation):
    return {"id": id, "type": "text", "prompt": prompt, "acceptedAnswers": answers, "explanation": explanation, "skill": "accuracy", "layer": "communicate", "sourceRefs": [], "origin": "supplementary"}


def task(id, title, prompt, scaffold, challenge, model, type="writing", minimum=140):
    return {"id": id, "title": title, "type": type, "prompt": prompt, "scaffold": scaffold, "challenge": challenge, "model": model, "minCharacters": minimum, "criteria": [c["id"] for c in CRITERIA], "sourceRefs": [], "origin": "supplementary"}


