    c["readings"] = [{"id": "care-complaint", "title": "A room that is too noisy", "context": "Fictional service constraints: another room is not yet confirmed; the receptionist must ask a supervisor about compensation.", "body": ["客人：昨晚走廊一直有噪音，我几乎没睡。我已经告诉前台一次了，但没有人回复。明天我还要很早出发。", "值班记录：请先了解噪音发生的时间与位置，并向客人道歉。可以联系值班同事处理现场情况。是否有安静的空房需要核实；补偿须由主管确认。请与客人约定下次联系的时间，并记录处理结果。"], "origin": "supplementary", "sourceRefs": []}]
    c["patterns"] = [{"id": "care-cause", "title": "由于…因此… · cause and consequence", "explanation": "由于 introduces a cause; 因此 introduces its result. In a complaint response, explain a constraint briefly after acknowledging the impact. A cause should not become an excuse.", "examples": ["由于换房需要先核实房态，因此目前还无法确认。"], "sourceRefs": [], "origin": "supplementary"}, {"id": "care-concession", "title": "尽管…，还是… · acknowledge a contrast", "explanation": "尽管 introduces a known fact; 还是 introduces a result that persists despite it. Compare with 如果, which introduces a condition that may or may not occur.", "examples": ["尽管我们已经联系了相关同事，还是需要再次确认处理结果。"], "sourceRefs": [], "origin": "supplementary"}]
    c["questions"] = [choice("care-q1", "What makes this complaint more serious than noise alone?", ["The guest has already reported it and received no follow-up.", "The guest asks for a luxury suite.", "The guest has confirmed the source of the noise."], 0, "The failure to reply has damaged trust. A response should address both the disturbance and the missed follow-up.", reading_id="care-complaint"), choice("care-q2", "Which action is within the stated authority?", ["Promise a full refund immediately.", "Guarantee a room is available before checking.", "Contact the duty team and agree a follow-up time."], 2, "The record permits coordination and follow-up. Room changes need checking and compensation needs supervisor confirmation.", "communication", "apply", "care-complaint"), cloze("care-q3", "Complete: ____我们已经联系了相关同事，还是需要再次确认处理结果。", ["尽管"], "尽管 introduces a concession about something that has already happened."), choice("care-q4", "Choose the most appropriate opening.", ["别的客人都没意见。", "很抱歉噪音影响了您的休息，也很抱歉之前没有及时回复。", "您应该早点睡。"], 1, "Acknowledge the specific impact and the missed response without blaming the guest.", "audience", "communicate")]
    c["tasks"] = [task("care-reply", "Restore trust in writing", "Write a 160–240-character Chinese reply. Acknowledge both problems, ask one clarifying question, offer only actions permitted by the duty record, and propose a specific follow-up time as your training plan. Do not guarantee compensation or an unverified room change.", ["很抱歉…，也很抱歉…", "为了尽快处理，请问…？", "我会先…，并…", "我将在…再次与您联系。"], "The guest insists on an immediate refund. Explain the approval boundary while maintaining empathy.", "很抱歉走廊的噪音影响了您的休息，也很抱歉您之前反映后没有得到及时回复。我们理解您明天需要早起，希望尽快改善您的休息环境。请问噪音主要发生在什么时间、靠近哪个位置？我会立即联系值班同事处理，并为您核实是否有更安静的空房。目前还不能保证换房，补偿方案也需要主管确认。我将在十五分钟后再次与您联系，告知处理进展；如果仍未解决，我们会继续协调下一步安排。"), task("care-call", "Handle the follow-up call", "Role-play a 2-minute follow-up call with a partner. The noise has reduced but the guest is still dissatisfied. Confirm the impact, summarize the action taken and agree the next step. Save a transcript or reflection.", ["Check whether the situation has improved.", "Acknowledge what remains unresolved.", "Confirm who will do what next."], "Your partner interrupts twice. Use a respectful clarification strategy.", "请问现在的噪音是否有所减轻？我理解您仍然担心今晚的休息。我会继续核实房态，并在约定时间前回复您。", "roleplay", 50)]

